class Solution {
public:
    long long minimumRemoval(vector<int>& beans) {
        sort(beans.begin(), beans.end());
        int n = beans.size();
        long long total = 0;
        for (int i = 0; i < n; i++) {
            total += beans[i];
        }
        long long best = total;
        for (int i = 0; i < n; i++) {
            long long kept = (long long)(n - i) * beans[i];
            long long removed = total - kept;
            if (removed < best) {
                best = removed;
            }
        }
        return best;
    }
};
